export const RECOMMENDED_DELIVERY_ARTWORKS = Object.freeze(["delivery-multilingual-1","delivery-agent-1","delivery-reasoning-1","delivery-quality-1","delivery-multimodal-1","delivery-evaluation-1","delivery-dialect-1"]);

const artworkById = new Map(BADGE_ARTWORKS.map(item => [item.id, item]));
const framedImages = new Set(BADGE_ARTWORKS.flatMap(item => Object.values(item.states)));

export function getBadgeArtwork(id) {
  return artworkById.get(id) || null;
}

export function badgeArtworkImage(id, level = 1) {
  const artwork = getBadgeArtwork(id);
  const key = String(level);
  return artwork && Object.prototype.hasOwnProperty.call(artwork.states, key) ? artwork.states[key] : '';
}

/** Only known bundled level images are allowed; arbitrary local or remote paths are not. */
export function isBuiltinBadgeImage(source) {
  return typeof source === 'string' && framedImages.has(source);
}

/** A duplicated label never chooses one of the differently categorized artworks implicitly. */
export function findBadgeArtworkByName(name) {
  if (typeof name !== 'string' || !name.trim()) return null;
  const matches = BADGE_ARTWORKS.filter(item => item.name === name.trim());
  return matches.length === 1 ? matches[0] : null;
}
